def build_config(defaults, file_config, env):
    # Regression: this is shallow, applies precedence backwards, and leaks strings.
    result = dict(file_config)
    result.update(defaults)
    server = result.setdefault('server', {})
    if 'APP_HOST' in env:
        server['host'] = env['APP_HOST']
    if 'APP_PORT' in env:
        server['port'] = env['APP_PORT']
    if 'APP_TLS_ENABLED' in env:
        server.setdefault('tls', {})['enabled'] = bool(env['APP_TLS_ENABLED'])
    return result

