class SingleFlightCache:
    def __init__(self):
        self._values = {}

    def get(self, key, loader):
        if key not in self._values:
            self._values[key] = loader()
        return self._values[key]

    def invalidate(self, key=None):
        if key is None:
            self._values.clear()
        else:
            self._values.pop(key, None)

